import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`catering-proposal`,heroTitle:`Build winning catering proposals in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded event brief, plans the menu and staffing, and drafts a polished catering proposal automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your event brief`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded an event brief, RFP, or planning notes. Build a complete catering proposal. (1) Extract event type, guest count, dietary requirements, service style, schedule, venue constraints, and budget context from the uploaded materials. (2) Recommend a menu structure, staffing plan, rentals, and service timeline based on the event needs. (3) Build pricing with food cost, staffing, rentals, service fees, and optional upgrades. (4) Draft proposal sections for menu, staffing, event flow, assumptions, and next steps. (5) Highlight operational risks or missing information that should be confirmed before sending. (6) Deliver a polished catering proposal that is ready for the client.`,heroOverlaySteps:[`Extracting guest count, service style, venue needs, and dietary requirements from your files`,`Planning the menu, staffing, rentals, and event timeline`,`Building pricing options with margins and upgrade paths`,`Client-ready catering proposal ready to send`],generatingSteps:[`Reading the uploaded event brief, planning notes, and venue requirements`,`Designing an agent to turn the event scope into menu and staffing recommendations`,`Configuring pricing logic for food cost, rentals, service fees, and upgrades`,`Preparing a polished catering proposal with timeline, assumptions, and next steps`],featureSectionTitle:`From event brief to client-ready proposal`,featureCardTitles:[`Connects to your event workflow`,`Proposals built around margin and logistics`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, internal planning notes, and proposal workflows stay connected so menus, pricing, and approvals move faster.`,`Menu structure. Staffing plan. Pricing options. Event assumptions. Computer gives your team a proposal draft that is ready for client review.`],capabilitySectionTitle:`Your event proposal team, on autopilot`,capabilitySectionSubtitle:`Upload the brief, get back a catering proposal built around the event details.`,capabilityCards:[{title:`Event Brief Analysis`,description:`Computer can extract guest count, event style, venue constraints, timing, and dietary needs from RFPs and planning documents.`},{title:`Menu & Staffing Plan`,description:`Computer can recommend menu structure, staffing levels, rentals, and service flow so your proposal reflects the actual event complexity.`},{title:`Cost & Margin Pricing`,description:`Computer can organize food cost, labor, rentals, and service fees into pricing options with room for upgrades and clear assumptions.`},{title:`Connect Your Tools`,description:`Computer can keep proposal drafts organized across docs, sheets, and planning workflows so internal review is easier for your team.`},{title:`Knows Your Packages`,description:`Computer can remember your preferred menu formats, service packages, and pricing structure across sessions so new proposals stay consistent.`},{title:`Client Follow-Up Assets`,description:`Computer can prepare recap notes, questions, and revision-ready proposal updates so you can move quickly after client feedback.`}]});export{t as default};
